describe('Async PDF Generation Download', () => {
  const downloadsFolder = Cypress.config('downloadsFolder');
  const pdfFileName = 'generated-document.pdf';

  beforeEach(() => {
    cy.visit('/pdf-generator');
    cy.clearDownloads();
  });

  it('should generate and download PDF when ready', () => {
    cy.get('[data-testid="pdf-form"]').should('be.visible');
    cy.get('[data-testid="document-title"]').type('Test Document');
    cy.get('[data-testid="document-content"]').type('This is test content for PDF generation');

    cy.get('[data-testid="generate-pdf-btn"]').click();

    cy.get('[data-testid="generation-status"]', { timeout: 10000 })
      .should('contain', 'Generating...');

    cy.get('[data-testid="download-btn"]', { timeout: 15000 })
      .should('be.enabled')
      .and('contain', 'Download PDF');

    cy.get('[data-testid="download-btn"]').click();

    cy.readFile(`${downloadsFolder}/${pdfFileName}`, 'binary', { timeout: 5000 })
      .should('exist')
      .then((fileContent) => {
        expect(fileContent.length).to.be.greaterThan(0);
        expect(fileContent.substring(0, 4)).to.equal('%PDF');
      });

    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .and('contain', 'PDF downloaded successfully');
  });

  it('should handle PDF generation timeout gracefully', () => {
    cy.get('[data-testid="document-title"]').type('Large Document');
    cy.get('[data-testid="document-content"]').type('x'.repeat(50000));

    cy.get('[data-testid="generate-pdf-btn"]').click();

    cy.get('[data-testid="generation-status"]', { timeout: 10000 })
      .should('contain', 'Generating...');

    cy.get('[data-testid="error-message"]', { timeout: 20000 })
      .should('be.visible')
      .and('contain', 'Generation timeout');

    cy.get('[data-testid="download-btn"]')
      .should('be.disabled');

    cy.get('[data-testid="retry-btn"]')
      .should('be.visible')
      .and('be.enabled');
  });

  it('should show progress updates during PDF generation', () => {
    cy.get('[data-testid="document-title"]').type('Progress Test Document');
    cy.get('[data-testid="document-content"]').type('Content for progress tracking');

    cy.get('[data-testid="generate-pdf-btn"]').click();

    cy.get('[data-testid="progress-bar"]', { timeout: 10000 })
      .should('be.visible');

    cy.get('[data-testid="progress-percentage"]')
      .invoke('text')
      .then((text) => {
        const percentage = parseInt(text);
        expect(percentage).to.be.greaterThan(0);
        expect(percentage).to.be.lessThanOrEqual(100);
      });

    cy.get('[data-testid="progress-percentage"]', { timeout: 15000 })
      .should('contain', '100');

    cy.get('[data-testid="download-btn"]')
      .should('be.enabled');
  });

  it('should prevent multiple simultaneous PDF generation requests', () => {
    cy.get('[data-testid="document-title"]').type('First Document');
    cy.get('[data-testid="document-content"]').type('First content');

    cy.get('[data-testid="generate-pdf-btn"]').click();

    cy.get('[data-testid="generate-pdf-btn"]')
      .should('be.disabled');

    cy.get('[data-testid="generate-pdf-btn"]').click({ force: true });

    cy.get('[data-testid="error-message"]')
      .should('contain', 'PDF generation already in progress');

    cy.get('[data-testid="download-btn"]', { timeout: 15000 })
      .should('be.enabled');

    cy.get('[data-testid="generate-pdf-btn"]')
      .should('be.enabled');
  });

  it('should download PDF with correct filename and metadata', () => {
    const customFileName = 'my-custom-report';

    cy.get('[data-testid="document-title"]').type('Custom Report');
    cy.get('[data-testid="document-content"]').type('Report content here');
    cy.get('[data-testid="filename-input"]').type(customFileName);

    cy.get('[data-testid="generate-pdf-btn"]').click();

    cy.get('[data-testid="download-btn"]', { timeout: 15000 })
      .should('be.enabled')
      .click();

    cy.readFile(`${downloadsFolder}/${customFileName}.pdf`, 'binary', { timeout: 5000 })
      .should('exist');

    cy.get('[data-testid="file-info"]')
      .should('contain', customFileName)
      .and('contain', 'PDF');
  });
});
